from collections import Counter

def delayedCount(nums: list[int], k: int) -> list[int]:
    n = len(nums)
    res = [0] * n
    freq = Counter()
    for i in range(n):
        if i >= k:
            freq[nums[i - k]] += 1
        res[i] = freq[nums[i]]
    return res

#include <vector>
#include <unordered_map>

class Solution {
public:
    std::vector<int> delayedCount(std::vector<int>& nums, int k) {
        int n = nums.size();
        std::vector<int> res(n, 0);
        std::unordered_map<int, int> freq;
        for (int i = 0; i < n; ++i) {
            if (i >= k) {
                freq[nums[i - k]]++;
            }
            res[i] = freq[nums[i]];
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public int[] delayedCount(int[] nums, int k) {
        int n = nums.length;
        int[] res = new int[n];
        Map<Integer, Integer> freq = new HashMap<>();
        for (int i = 0; i < n; i++) {
            if (i >= k) {
                freq.put(nums[i - k], freq.getOrDefault(nums[i - k], 0) + 1);
            }
            res[i] = freq.getOrDefault(nums[i], 0);
        }
        return res;
    }
}

